solution.solution.py:
class Account:
    def __init__(self, owner, balance=0):
        self.owner = owner
        self.balance = balance

    @property
    def balance(self):
        return self._balance

    @balance.setter
    def balance(self, value):
        if value < 0:
            raise ValueError("the balance cannot be negative")
        self._balance = value

    def deposit(self, amount):
        if amount <= 0:
            raise ValueError("deposit a positive amount")
        self.balance += amount

unitTests:
@test("reading and depositing")
def _():
    a = Account("Ada", 10)
    a.deposit(5)
    check_eq(a.balance, 15)
    check_eq(Account("Bo").balance, 0)

@test("negative balances are refused")
def _():
    a = Account("Ada", 10)
    def set_negative():
        a.balance = -1
    check_raises(ValueError, set_negative)
    check_eq(a.balance, 10)
    check_raises(ValueError, Account, "Cy", -5)

@test("bad deposits are refused")
def _():
    a = Account("Ada")
    check_raises(ValueError, a.deposit, 0)
    check_raises(ValueError, a.deposit, -3)

@test("it is a property")
def _():
    check(isinstance(Account.__dict__.get("balance"), property), "balance should be a property")

